		/**
		 * Allowed preset keys.
		 *
		 * @return array<int, string>
		 */
		public static function allowed_keys() {
			return array_keys( self::paths() );
		}

		/**
		 * Get inline SVG markup for a preset key (falls back to the default).
		 *
		 * @param string $key Preset key.
		 * @return string Inline SVG markup.
		 */
		public static function get( $key ) {
			$paths = self::paths();
			$inner = isset( $paths[ $key ] ) ? $paths[ $key ] : $paths[ self::DEFAULT_KEY ];

			return '<svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">' . $inner . '</svg>';
		}
